def max_concurrency(gpu_gb, model_gb, layers, seq_len, kv_heads, head_dim=128, bytes_per=2):
    per = 2 * layers * seq_len * kv_heads * head_dim * bytes_per / (1024 ** 3)
    if per <= 0:
        return 0
    remain = gpu_gb - model_gb
    if remain <= 0:
        return 0
    return int(remain // per)


